/** Only a Google Maps directions URL generated by the app may be opened from notification data. */
export function notificationRouteLink(data: unknown): string | null {
  if (!data || typeof data !== 'object') return null;
  const value = data as Record<string, unknown>;
  if (typeof value.googleMapsUrl !== 'string' || value.googleMapsUrl.length > 2048) return null;
  try {
    const url = new URL(value.googleMapsUrl);
    return url.protocol === 'https:' && (url.hostname === 'www.google.com' || url.hostname === 'maps.google.com')
      && !url.port && !url.username && !url.password
      && url.pathname === '/maps/dir/' && url.searchParams.get('api') === '1'
      && !!url.searchParams.get('origin') && !!url.searchParams.get('destination') ? url.toString() : null;
  } catch {
    return null;
  }
}
